#include <plc.hpp>

// Official editor serialization candidate only. Do not RUN or trigger Execute.
// Only memory inputs and status stores; no physical I/O or transport callback.
plc::ReadVar remote{0,plc::Link::Serial1,1,100,plc::Object::DiscreteInputs,17,17,200};

void scan() {
    remote.update(plc::read_m(10), plc::read_m(13));
    plc::write_m(14, remote.done());
    plc::write_m(15, remote.busy());
    plc::write_m(16, remote.aborted());
    plc::write_m(17, remote.error());
}

